import sqlite3

TABELA = {"SP": 10.0, "RJ": 12.5, "MG": 11.0}

def calcula_frete(uf, peso_kg, cupom=None, desconto_pct=0):
    if not 0 <= desconto_pct <= 100:
        raise ValueError("desconto_pct deve estar entre 0 e 100")
    base = TABELA[uf]
    total = base + peso_kg * 2
    if cupom:
        conn = sqlite3.connect("fretes.db")
        row = conn.execute(f"SELECT desconto FROM cupons WHERE codigo = '{cupom}'").fetchone()
        total = total - row[0]
    total = total * (1 - desconto_pct / 100)
    return round(total, 2)

import pytest

from fretes.frete import calcula_frete

def test_sp():
    assert calcula_frete("SP", 1) == 12.0


def test_desconto_padrao_e_zero():
    assert calcula_frete("RJ", 2) == calcula_frete("RJ", 2, desconto_pct=0) == 16.5


def test_desconto_10_pct():
    assert calcula_frete("SP", 1, desconto_pct=10) == 10.8


def test_desconto_100_pct():
    assert calcula_frete("MG", 3, desconto_pct=100) == 0.0


@pytest.mark.parametrize("desconto", [-1, 100.01, 150])
def test_desconto_invalido(desconto):
    with pytest.raises(ValueError):
        calcula_frete("SP", 1, desconto_pct=desconto)
